93	 * an exact inventory has to be pinned from: what the console said, what the
94	 * browser failed to fetch, what the page threw, and where it navigated.
95	 */
96	function pageSummary(receiptPath: string): unknown {
97		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
98			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
99		};
100		const page = receipt.boxes?.[0]?.pages?.[0];
101		if (page === undefined) return null;
102		return {
103			consoleMessages: page.consoleMessages,
104			pageErrors: page.pageErrors,
105			failedRequests: page.failedRequests,
106			navigations: page.navigations,
107		};
108	}
109	
110	export async function calibrateAngularSuperProductivityLane(
111		lane: 'baseline' | 'migrated',
112	): Promise<void> {
113		const laneRoot = laneRoots[lane];
114		const receiptDir = join(
115			root,
116			'.versionless/stage/witness-angular-super-productivity-calibrate',
