121			chromiumExecutable: join(
122				root,
123				'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
124			),
125			contextProfile: 'current-witness',
126			viewport: VIEWPORT,
127			// The reader is an opt-in and this driver opts in, because reading the
128			// store's keys either side of a create is the whole of leg (e).
129			indexedDb: 'read-keys',
130			// The application's own `index.html` links the Roboto stylesheet, so the
131			// seam is answered inside the context with an empty body exactly as the
132			// TinyTranslator vertical answers its icon stylesheet. Nothing leaves the
133			// machine, and the request is still observed.
134			transport: async () => ({
135				action: 'fulfill',
136				status: 200,
137				contentType: 'text/css',
138				body: Buffer.alloc(0),
139			}),
140		});
141		const counts: Record<string, number | string> = {};
142		let telemetry: unknown;
143		let storage: unknown;
144		let scroll: unknown;
145		const legs: Record<string, unknown> = {};
146		const definition = box(`super-productivity-calibrate-${lane}`, async (context) => {
147			const page = await context.browser.visit(joinURL(staticServer.origin, INITIAL_ROUTE));
148			for (const selector of CANDIDATES) {
149				// Asked for as zero: a candidate that genuinely resolves nothing passes
150				// and is recorded as absent, and one that resolves reports its actual
151				// count in the refusal, which is the measurement being asked for.
152				try {
153					await context.expect.page.count(page, selector, 0);
154					counts[selector] = 0;
155				} catch (error: unknown) {
156					counts[selector] = (error instanceof Error ? error.message : String(error))
157						.split('\n')[0]!
158						.trim();
159				}
160			}
161			telemetry = await host.serviceWorkerTelemetry(10_000);
162			storage = await host.browserStorageKeys();
163			scroll = await host.viewportScroll();
164	
165			// Legs (a) and (e), driven here before either is pinned into a journey.
166			// Every reading is printed rather than asserted: what this pass is for is
167			// finding out what the application does, and an assertion written before
168			// the reading exists is a guess with a stack trace.
169			const titleProbe = { group: 'task', name: '.task-title', item: '.task-title' } as const;
170			const report = async (stage: string): Promise<void> => {
171				legs[stage] = {
172					indexedDb: await host.indexedDbKeys().then(
173						(inventory) => inventory,
174						(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
175					),
176					localStorage: await host.browserStorageKeys(),
177					taskTitles: await host.groupedText(titleProbe).then(
178						(groups) => groups,
179						(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
180					),
181					scroll: await host.viewportScroll(),
182				};
183			};
184			legs['renderedStyles'] = await host.renderedStyles(
185				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => ({
186					label: probe.label,
187					selector: probe.selector,
188					properties: [...probe.properties],
189				})),
190			);
191			await report('before-create');
192			await page.trackEvents('click', 'input', 'keydown');
193			await page.type('add-task-bar input', 'Witness calibration task', { redact: false });
194			await page.press('add-task-bar input', 'Enter');
195			await new Promise<void>((settle) => void setTimeout(settle, 1_500));
196			await report('after-create');
197			await page.reload();
198			await new Promise<void>((settle) => void setTimeout(settle, 2_500));
199			await report('after-reload');
200			legs['after-reload-telemetry'] = await host.serviceWorkerTelemetry(10_000);
201			for (const selector of ['task-list', 'task-list task', 'task', 'task .task-title']) {
202				try {
203					await context.expect.page.count(page, selector, 0);
204					legs[`count:${selector}`] = 0;
205				} catch (error: unknown) {
206					legs[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
207						.split('\n')[0]!
208						.trim();
209				}
210			}
211	
212			// Legs (c) time-tracking and (b) drag reorder, driven here for the first
213			// time before either is pinned. A second task is created so the reorder
214			// has a permutation to settle into, and every reading is printed.
215			const iconProbe = { group: 'main-header .play-btn', name: 'mat-icon', item: 'mat-icon' } as const;
216			const readIcon = async (): Promise<unknown> =>
217				host.groupedText(iconProbe).then(
218					(groups) => groups.flatMap((group) => group.items),
219					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
220				);
221			const readTitles = async (): Promise<unknown> =>
222				host.groupedText({ group: 'task', name: '.task-title', item: '.task-title' } as const).then(
223					(groups) => groups.map((group) => group.name),
224					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
225				);
226			const cb: Record<string, unknown> = {};
227			// Assigned before the drives so a step that throws still leaves every
228			// reading taken up to that point in the printed record, rather than losing
229			// the whole block to one refusal.
230			legs['legs-c-b'] = cb;
231			await page.type('add-task-bar input', 'Witness calibration task two', { redact: false });
232			await page.press('add-task-bar input', 'Enter');
233			await new Promise<void>((settle) => void setTimeout(settle, 1_000));
234			cb['titles-after-second-create'] = await readTitles();
235			for (const selector of [
236				'main-header .play-btn',
237				'task .play-icon-indicator',
238				'task .time-wrapper',
239				'task .time-wrapper .time-val',
240				'task .drag-handle',
241				'task .drag-handle.handle-par',
242				'.task-list-inner',
243				'.task-list-inner[dragula]',
244			]) {
245				try {
246					await context.expect.page.count(page, selector, 0);
247					cb[`count:${selector}`] = 0;
248				} catch (error: unknown) {
249					cb[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
250						.split('\n')[0]!
251						.trim();
252				}
253			}
254			// Leg (c): the icon flip on the global tracking control.
255			cb['icon-before-start'] = await readIcon();
256			try {
257				await page.click('main-header .play-btn');
258				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
259				cb['icon-after-start'] = await readIcon();
260				cb['play-indicator-after-start'] = await host
261					.groupedText({ group: 'task .play-icon-indicator', name: 'task .play-icon-indicator', item: 'task .play-icon-indicator' } as const)
262					.then((g) => g.length, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
263				cb['time-val-after-start'] = await host
264					.groupedText({ group: 'task .time-wrapper', name: '.time-val', item: '.time-val' } as const)
265					.then((g) => g, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
266				await page.click('main-header .play-btn');
267				await new Promise<void>((settle) => void setTimeout(settle, 800));
268				cb['icon-after-stop'] = await readIcon();
269			} catch (error: unknown) {
270				cb['time-tracking-error'] = error instanceof Error ? error.message : String(error);
271			}
272			// Leg (b): the dragula reorder, initiated on the parent drag handle.
273			cb['order-before-drag'] = await readTitles();
274			try {
275				await page.drag(
276					'task-list:first-of-type task:nth-of-type(1) .drag-handle.handle-par',
277					'task-list:first-of-type task:nth-of-type(2) .drag-handle.handle-par',
278					{ steps: 24 },
279				);
280				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
281				cb['order-after-drag'] = await readTitles();
282				cb['indexeddb-after-drag'] = await host
283					.indexedDbKeys()
284					.then((i) => i, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
285			} catch (error: unknown) {
286				cb['drag-error'] = error instanceof Error ? error.message : String(error);
287			}
288			cb['pageErrors-during-cb'] = 'see page summary';
289			await context.receipt.capture('calibration-complete');
290		});
291		let status = 'unknown';
292		let failure = '';
293		let receiptPath = '';
294		try {
295			const result = await runBoxes({
296				root: laneRoot,
297				boxes: [
298					{
299						file: join(laneRoot, 'versionless-runtime.box.ts'),
300						relativeFile: 'versionless-runtime.box.ts',
301						exportName: 'default',
302						box: definition,
303					},
304				],
305				receiptDir,
306				assertionTimeoutMs: 10_000,
307				fileSystem: witnessNodeFileSystem,
308				browser: host.browser,
309				headless: true,
310			});
311			status = result.status;
312			failure = result.boxes[0]?.error?.message ?? '';
313			receiptPath = result.receiptPath;
314		} finally {
315			await staticServer.close();
316		}
317		process.stdout.write(
318			`${canonicalize({
319				lane,
320				status,
321				failure,
322				receiptPath,
323				counts,
324				telemetry,
325				storage,
326				scroll,
327				legs,
328				page: receiptPath === '' ? null : pageSummary(receiptPath),
329				requestOutcomes: host.requestOutcomes(),
330				staticPaths: staticServer.requests(),
331			})}\n`,
332		);
333	}
334	
335	export async function main(args = process.argv.slice(2)): Promise<void> {
336		const lane = args[0];
337		if (lane !== 'baseline' && lane !== 'migrated')
338			throw new Error('Super Productivity calibration requires a lane: baseline or migrated');
339		await calibrateAngularSuperProductivityLane(lane);
340	}
341	
342	if (basename(process.argv[1] ?? '') === 'angular-super-productivity-calibrate-run.ts')
343		main().catch((error: unknown) => {
344			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
345			process.exitCode = 1;
346		});
