	baseline: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAMS,
	migrated: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAMS,
}) as Readonly<Record<'baseline' | 'migrated', readonly WitnessMockedNonLoopbackSeamEntry[]>>;

